            Shares sh = shares.get(pool.getId());
            List<BigDecimal> poolCuts = cutsOf(pool.getId(), shares, parentOf, pot, cuts, new HashSet<>());
            List<MemberView> views = new ArrayList<>();
            for (int i = 0; i < sh.listed().size(); i++) {
